// The mtime both call files (buckets.json, chase.json) are stat'ed with.
export const BOARD_WRITTEN = Date.parse("2026-10-11T07:22:45Z")
export const TILES: Record<string, number> = {"Open pull requests":19,"Open issues":12,"You owe the next move":0,"PRs waiting on the author":9,"Nobody has looked":2,"Parked or draft":8,"Issues on a maintainer call":2,"PRs disposed, 7 days":152,"Net PR change, 7 days":-8}

// I2a: the 07:35 answers predate the labels, assignees and totals the queue document now asks for. LIVE_QUEUES adds
// them, synthetic and stated here: no labels and no assignees (the board's parked stays sticky), and each review and
// comment window whole when it held fewer than the ten asked for (true of last: 10) and one longer than read when
// full (an assumption that can only leave a group undecided, never wrong). QUEUES stays as read.
// I2c: they predate the issue fields too. Each issue still open at 21:42 takes its author, labels and closing PRs from
// that read (tests/live-fixtures.ts) and its comments as they stood at 07:35:12, later ones dropped and the total cut by
// as many; an issue closed in between keeps none, which leaves it undecided.
const window = (list: { nodes: unknown[] }) => ({ totalCount: list.nodes.length < 10 ? list.nodes.length : list.nodes.length + 1, ...list })
const AT_0735 = Date.parse('2026-10-11T07:35:12Z')
function issueAt0735(repo: string, issue: { number: number }) {
  const later = QUEUES_2145[repo]?.data.repository.issues.nodes.find((one: { number: number }) => one.number === issue.number)
  if (later === undefined) return
  const said = later.comments.nodes.filter((one: { createdAt: string }) => Date.parse(one.createdAt) <= AT_0735)
  const comments = { totalCount: later.comments.totalCount - (later.comments.nodes.length - said.length), nodes: said }
  const { author, authorAssociation, labels, closedByPullRequestsReferences } = later
  Object.assign(issue, { author, authorAssociation, comments, labels, closedByPullRequestsReferences })
}
export const LIVE_QUEUES: Record<string, unknown> = Object.fromEntries(
  Object.entries(QUEUES).map(([repo, answer]) => {
    const copy = JSON.parse(JSON.stringify(answer))
    for (const pr of copy.data.repository.pullRequests.nodes) {
      Object.assign(pr, {
        reviews: window(pr.reviews),
        comments: window(pr.comments),
        labels: { totalCount: 0, nodes: [] },
        assignees: { totalCount: 0, nodes: [] },
      })
    }
    for (const issue of copy.data.repository.issues.nodes) issueAt0735(repo, issue)
    return [repo, copy]
  }),
)

// Built pull requests for the group rules (tests/groups.test.ts): a word is who said it, as what, and when (an hour
// on 2026-10-11, UTC); bot marks a Bot account.
export type Word = { login: string; as?: string; isBot?: true; hour: number; body?: string }
export const VIEWER_LOGIN = 'IsmaelMartinez'
export const hourOf = (hour: number) => `2026-10-11T${String(hour).padStart(2, '0')}:00:00Z`

export function pull(
  number: number,
  spec: {
    author?: string
    isDraft?: true
    reviews?: Word[]
    comments?: Word[]
    commit?: { login: string; hour: number }
    labels?: string[]
    assignees?: string[]
    reviewTotal?: number
    commentTotal?: number
    labelTotal?: number
    assigneeTotal?: number
  } = {},
) {
  const node = (word: Word, field: string) => ({
    author: { login: word.login, __typename: word.isBot ? 'Bot' : 'User' },
    authorAssociation: word.as ?? 'NONE',
    [field]: hourOf(word.hour),
    ...(word.body === undefined ? {} : { body: word.body }),
  })
  const reviews = spec.reviews ?? []
  const comments = spec.comments ?? []
  const labels = spec.labels ?? []
  const assignees = spec.assignees ?? []
  const mine = reviews.filter(word => word.login === VIEWER_LOGIN).slice(-1)
  return {
    number,
    title: `Built PR ${number}`,
    createdAt: hourOf(1),
    isDraft: spec.isDraft === true,
    headRefOid: 'a'.repeat(40),
    author: { login: spec.author ?? 'contributor', __typename: 'User' },
    mine: { nodes: mine.map(word => ({ submittedAt: hourOf(word.hour), commit: { oid: 'b'.repeat(40) } })) },
    reviews: { totalCount: spec.reviewTotal ?? reviews.length, nodes: reviews.map(word => node(word, 'submittedAt')) },
    comments: { totalCount: spec.commentTotal ?? comments.length, nodes: comments.map(word => node(word, 'createdAt')) },
    commits: { nodes: spec.commit === undefined ? [] : [{ commit: { committedDate: hourOf(spec.commit.hour), author: { user: { login: spec.commit.login } } } }] },
    labels: { totalCount: spec.labelTotal ?? labels.length, nodes: labels.map(name => ({ name })) },
    assignees: { totalCount: spec.assigneeTotal ?? assignees.length, nodes: assignees.map(login => ({ login })) },
  }
}

export const answerOf = (prs: unknown[]) => ({
  data: {
    repository: {
      issues: { totalCount: 0, nodes: [] },
      pullRequests: { totalCount: prs.length, pageInfo: { hasNextPage: false }, nodes: prs },
    },
  },
})
